/**
 * Profile summaries (v1): subject sheets distilled from temporal day
 * summaries.
 *
 * Source of truth: the 21 most recent completed `day` summaries generated by
 * the current temporal prompt version (per-user material — day summaries
 * blend both sides of the conversation). The subject distinction comes from
 * the provisioned per-subject evidence rule
 * (`memory_subject.profile_evidence_rule`), appended to the table-provided
 * system prompt as the per-subject instruction block.
 * Regeneration is fingerprint-gated — unchanged inputs (prompt versions,
 * subject, and day-summary fingerprints) cost zero LLM calls and leave the
 * stored sheet byte-identical.
 *
 * The system prompt base is persona-bearing configuration and comes from the
 * `memory_prompt` table (kind `profile_summary`); neither it nor the
 * evidence rule is code content.
 */

import type { PostgresPool } from "@companion/postgres";

import type { MemoryConfig, } from "./config.ts";
import { taskPresets, type MemoryLlmCaller } from "./llm.ts";
import {
  PROFILE_RESPONSE_FORMAT,
  PROFILE_SUMMARY_PROMPT_VERSION,
  TEMPORAL_SUMMARY_PROMPT_VERSION,
  parseProfileV1Output,  promptContentHash,
} from "./prompts.ts";
import type { MemorySubject, ProfileSummary } from "./types.ts";
import { fingerprint, getProfileSummary, saveProfileSummary } from "./temporal/store.ts";

const MAX_SOURCE_SUMMARIES = 21;
const MAX_PER_SUMMARY_CHARS = 1000;
const MAX_CONTENT_CHARS = 4000;

export interface ProfileSummaryDeps {
  readonly pool: PostgresPool;
  readonly config: MemoryConfig;
  /** The provisioned subjects, used to resolve the subject's evidence rule. */
  readonly subjects: readonly MemorySubject[];
  readonly systemPrompt: string;
  readonly callLlm: MemoryLlmCaller;
}

interface DaySummaryRow {
  period_key: string;
  content: string;
  end_at: Date;
  fingerprint: string;
  message_count: number;
}

/**
 * The system prompt for one subject: the table-provided base prompt plus the
 * subject's provisioned evidence-attribution rule (source behavior: a
 * per-subject instruction block that decides what counts as evidence for
 * that subject).
 */
export function profileV1SystemPrompt(basePrompt: string, subject: MemorySubject): string {
  return `${basePrompt}\n\nSUBJECT EVIDENCE RULE\n${subject.profileEvidenceRule.trim()}`;
}

/**
 * Generate (or reuse) one subject's profile summary. Returns null when no
 * day summaries exist yet for the subject pipeline to distill.
 */
export async function generateProfileSummary(
  deps: ProfileSummaryDeps,
  subjectId: string,
  now: Date = new Date(),
): Promise<ProfileSummary | null> {
  const subject = deps.subjects.find((candidate) => candidate.id === subjectId);
  if (subject === undefined) {
    throw new Error(`Profile subject '${subjectId}' is not provisioned in memory_subject`);
  }
  const sourceDocuments = await deps.pool.query<DaySummaryRow>(
    `SELECT period_key, content, end_at, fingerprint, message_count
     FROM memory_temporal_summary
     WHERE kind = 'day' AND status = 'complete' AND end_at <= $1
       AND message_count > 0 AND prompt_version = $2
     ORDER BY end_at DESC
     LIMIT $3`,
    [now, TEMPORAL_SUMMARY_PROMPT_VERSION, MAX_SOURCE_SUMMARIES],
  );
  if (sourceDocuments.rows.length === 0) return null;

  const sourceSummaryKeys = sourceDocuments.rows.map(
    (source) => `summary:day:${source.period_key}`,
  );
  const sourceFingerprint = fingerprint([
    PROFILE_SUMMARY_PROMPT_VERSION,
    // Hash the FULL actual system prompt (base + the subject's private
    // evidence rule), not just the base: the rule is part of the prompt the
    // sheet was generated with, so a rule change must invalidate the cached
    // sheet and force regeneration.
    promptContentHash(profileV1SystemPrompt(deps.systemPrompt, subject)),
    TEMPORAL_SUMMARY_PROMPT_VERSION,
    subjectId,
    ...sourceDocuments.rows.map(
      (source) => `${source.period_key}:${source.fingerprint}`,
    ),
  ]);
  const existing = await getProfileSummary(deps.pool, subjectId);
  if (existing?.status === "complete" && existing.sourceFingerprint === sourceFingerprint) {
    return existing;
  }

  const sourceIds = new Set(sourceSummaryKeys);
  const sourceText = sourceDocuments.rows.map((source) =>
    [
      `SOURCE id=summary:day:${source.period_key}`,
      `periodEnd=${source.end_at.toISOString()}`,
      source.content.slice(0, MAX_PER_SUMMARY_CHARS),
      `END_SOURCE id=summary:day:${source.period_key}`,
    ].join("\n"),
  ).join("\n\n");

  const result = await deps.callLlm({
    systemPrompt: profileV1SystemPrompt(deps.systemPrompt, subject),
    userMessage: `Subject: ${subjectId}\n\nSOURCE MATERIAL\n${sourceText}\nEND SOURCE MATERIAL`,
    taskPreset: taskPresets(deps.config).profileSummary,
    responseFormat: PROFILE_RESPONSE_FORMAT,
  });
  const parsed = parseProfileV1Output(result.text);
  const safeClaims = parsed.claims
    .filter((claim) => claim.evidence.some((id) => sourceIds.has(id)))
    .map((claim) => ({
      text: claim.text,
      evidence: claim.evidence.filter((id) => sourceIds.has(id)),
    }));
  const content = [
    parsed.profile,
    ...safeClaims.map((claim) => `- ${claim.text}`),
  ].filter(Boolean).join("\n").slice(0, MAX_CONTENT_CHARS);

  const summary: ProfileSummary = {
    subject: subjectId,
    content,
    sourceSummaryKeys,
    sourceFingerprint,
    model: result.model || deps.config.model,
    promptVersion: PROFILE_SUMMARY_PROMPT_VERSION,
    status: "complete",
    generatedAt: new Date(),
  };
  await saveProfileSummary(deps.pool, { ...summary, error: null });
  return summary;
}
